import java.util.*;
public class Main {
    static int discounted(int price,int rate){if(price<0||rate<0||rate>100)throw new IllegalArgumentException();return price-price*rate/100;}
    public static void main(String[] args){Scanner s=new Scanner(System.in);int n=s.nextInt();int passed=0;for(int i=1;i<=n;i++){int price=s.nextInt(),rate=s.nextInt();String expected=s.next();String actual;try{actual=String.valueOf(discounted(price,rate));}catch(IllegalArgumentException e){actual="INVALID";}if(actual.equals(expected)){System.out.println(i+" PASS");passed++;}else System.out.println(i+" FAIL expected="+expected+" actual="+actual);}System.out.println("PASSED "+passed+"/"+n);}
}

