import java.util.*;
public class Main {
    static int[] parse(String v){String[] q=v.split("\\.",-1);return new int[]{Integer.parseInt(q[0]),Integer.parseInt(q[1])};}
    public static void main(String[] args){Scanner s=new Scanner(System.in);int n=s.nextInt();Map<String,Set<String>> versions=new TreeMap<>();for(int i=0;i<n;i++){String[] p=s.next().split(":",-1);versions.computeIfAbsent(p[0]+":"+p[1],k->new LinkedHashSet<>()).add(p[2]);}for(Map.Entry<String,Set<String>> e:versions.entrySet())if(e.getValue().size()>1)System.out.println("CONFLICT "+e.getKey());for(Map.Entry<String,Set<String>> e:versions.entrySet()){String best=null;for(String v:e.getValue()){if(best==null){best=v;continue;}int[] a=parse(v),b=parse(best);if(a[0]>b[0]||(a[0]==b[0]&&a[1]>b[1]))best=v;}System.out.println(e.getKey()+"="+best);}}
}
